/* app/globals.css */
:root{
 --bg:#fffdf8;--ink:#111;--muted:#666;--line:#171717;
 --moss:#b9d59f;--violet:#c9b9f4;--sun:#ffd45b;--water:#9edcea;--clay:#f3ad91;
 --sans:Arial,Helvetica,sans-serif;--serif:Georgia,"Times New Roman",serif
}
*{box-sizing:border-box}
html{scroll-behavior:smooth;background:var(--bg)}
body{margin:0;background:var(--bg);color:var(--ink);font-family:var(--sans);font-size:16px;line-height:1.5}
a{color:inherit;text-decoration:none}button,input,select{font:inherit}button{color:inherit}svg,img{display:block;max-width:100%}
::selection{background:#111;color:#fff}
.skip-link{position:fixed;z-index:9999;left:12px;top:12px;transform:translateY(-160%);background:#111;color:#fff;padding:10px 14px;border-radius:999px}.skip-link:focus{transform:none}
:focus-visible{outline:3px solid #111;outline-offset:4px}
.home-page{max-width:1240px;margin:auto;padding:0 22px 60px}
.home-header{height:90px;display:flex;align-items:center;justify-content:space-between;border-bottom:2px solid #111}
.home-brand{display:flex;align-items:baseline;gap:14px}.brand-mark,.mini-brand{font-weight:900;letter-spacing:-.06em;font-size:26px}.home-brand small{font-size:13px;color:var(--muted)}
.home-header nav{display:flex;gap:18px;font-weight:700;font-size:14px}.home-header nav a,.info-nav>a:last-child{border-bottom:2px solid transparent}.home-header nav a:hover,.info-nav>a:last-child:hover{border-color:#111}
.home-intro{padding:84px 0 66px;text-align:center}.home-intro h1{font-size:clamp(58px,9vw,118px);line-height:.88;letter-spacing:-.075em;margin:0;font-weight:900}.home-intro h1 span{font-family:var(--serif);font-weight:400;font-style:italic;letter-spacing:-.06em}
.home-intro p{font-size:clamp(17px,2vw,22px);max-width:690px;margin:28px auto 20px;color:#484848}.home-intro>a{display:inline-block;font-weight:800;border-bottom:2px solid #111}
.play-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}
.play-tile{min-height:500px;border:3px solid #111;border-radius:18px;box-shadow:0 6px 0 #111;overflow:hidden;padding:16px;display:grid;grid-template-rows:auto 1fr auto;transition:transform .15s ease,box-shadow .15s ease}
.play-tile:hover{transform:translateY(-4px);box-shadow:0 10px 0 #111}.play-tile:active{transform:translateY(2px);box-shadow:0 3px 0 #111}
.tile-moss{background:var(--moss)}.tile-violet{background:var(--violet)}.tile-sun{background:var(--sun)}.tile-water{background:var(--water)}.tile-clay{background:var(--clay)}
.tile-bar{display:flex;justify-content:space-between;font-size:12px;font-weight:900;text-transform:uppercase;letter-spacing:.08em}.tile-bar span{background:rgba(255,255,255,.75);border:2px solid #111;border-radius:999px;padding:5px 9px}
.tile-visual{display:grid;place-items:center;min-height:245px;padding:18px}.tile-art{width:min(100%,430px);height:auto;color:#111}.tile-art.compact{width:150px}
.tile-copy p{font-family:var(--serif);font-style:italic;margin:0 0 5px;font-size:16px}.tile-copy h2{font-size:clamp(34px,4vw,58px);line-height:.92;letter-spacing:-.055em;margin:0 0 18px}.tile-copy>div{display:flex;justify-content:space-between;border-top:2px solid #111;padding-top:10px;font-size:12px;font-weight:900;text-transform:uppercase;letter-spacing:.08em}
.home-note{padding:110px 0 100px;max-width:900px;margin:auto;text-align:center}.home-note>p{font-size:13px;font-weight:900;text-transform:uppercase;letter-spacing:.08em}.home-note h2{font-family:var(--serif);font-weight:400;font-size:clamp(38px,6vw,76px);line-height:1.02;letter-spacing:-.045em;margin:18px 0 28px}.home-note>div{display:flex;justify-content:center;gap:18px;flex-wrap:wrap}.home-note a{font-weight:800;border-bottom:2px solid #111}
.home-footer{border-top:2px solid #111;padding:22px 0 0;display:flex;justify-content:space-between;font-size:12px;font-weight:800;text-transform:uppercase;letter-spacing:.08em}
.experience-page{--accent:var(--clay);background:var(--bg)}.tone-moss{--accent:var(--moss)}.tone-violet{--accent:var(--violet)}.tone-sun{--accent:var(--sun)}.tone-water{--accent:var(--water)}.tone-clay{--accent:var(--clay)}
.experience-nav{position:fixed;z-index:100;left:18px;right:18px;top:16px;display:flex;justify-content:space-between;pointer-events:none}.experience-nav a{pointer-events:auto;background:rgba(255,253,248,.92);border:2px solid #111;box-shadow:0 3px 0 #111}.mini-brand{font-size:18px;padding:8px 12px;border-radius:999px}.close-experience{width:42px;height:42px;border-radius:50%;display:grid;place-items:center;font-size:26px;font-weight:800}
.experience-cover{min-height:100vh;background:var(--accent);display:grid;grid-template-columns:1.05fr .95fr;gap:40px;align-items:center;padding:100px clamp(24px,7vw,100px) 60px;border-bottom:3px solid #111}
.cover-copy{max-width:740px}.cover-meta{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:18px}.cover-meta span{background:rgba(255,255,255,.72);border:2px solid #111;border-radius:999px;padding:5px 9px;font-size:11px;font-weight:900;text-transform:uppercase;letter-spacing:.08em}
.cover-question{font-family:var(--serif);font-style:italic;font-size:clamp(18px,2vw,25px);margin:0 0 8px}.experience-cover h1{font-size:clamp(58px,8vw,112px);line-height:.87;letter-spacing:-.075em;margin:0 0 24px}
.cover-intro{font-size:clamp(17px,1.8vw,21px);max-width:650px;margin:0 0 28px}.cover-actions{display:flex;gap:16px;align-items:center;flex-wrap:wrap}.cover-start{background:#111;color:#fff;border:2px solid #111;border-radius:999px;padding:11px 16px;font-weight:900;box-shadow:0 4px 0 rgba(0,0,0,.25)}.cover-actions>span{font-size:12px;font-weight:800;text-transform:uppercase;letter-spacing:.07em}
.cover-art{display:grid;place-items:center}.cover-art .tile-art{width:min(100%,560px)}
.experience-body{background:var(--bg)}
.next-card{padding:90px 22px 100px;max-width:820px;margin:auto;text-align:center}.next-card>p{font-size:12px;font-weight:900;text-transform:uppercase;letter-spacing:.1em}.next-tile{border:3px solid #111;border-radius:18px;box-shadow:0 6px 0 #111;padding:16px;display:grid;grid-template-columns:auto 160px 1fr auto;align-items:center;gap:18px;text-align:left}.next-tile>div{display:flex;flex-direction:column;font-weight:900}.next-tile h2{font-size:28px;line-height:1;margin:0;letter-spacing:-.04em}.next-tile strong{font-size:13px}.back-collection{display:inline-block;margin-top:28px;font-weight:800;border-bottom:2px solid #111}
.instruction-banner{max-width:950px;margin:0 auto 22px;border:2px solid #111;border-radius:14px;padding:12px 14px;display:flex;gap:12px;background:#fff}.instruction-banner>span{font-size:11px;font-weight:900;text-transform:uppercase;letter-spacing:.1em}.instruction-banner p{margin:0;color:#4d4d4d}
.pill-button{border:2px solid #111;background:#111;color:#fff;border-radius:999px;padding:10px 15px;font-weight:900;cursor:pointer;box-shadow:0 3px 0 rgba(0,0,0,.25)}.text-button{border:0;border-bottom:2px solid #111;background:transparent;padding:3px 0;font-weight:900;cursor:pointer}
.tree-world{min-height:4400px;position:relative;background:linear-gradient(#e7f1d9 0%,#b9d59f 56%,#738a5e 100%)}
.tree-sticky{position:sticky;top:0;height:100vh;overflow:hidden;color:#18200f}.tree-year{position:absolute;z-index:5;top:70px;left:clamp(18px,5vw,70px);display:flex;flex-direction:column}.tree-year small{font-size:11px;text-transform:uppercase;font-weight:900;letter-spacing:.1em}.tree-year strong{font-size:clamp(70px,11vw,150px);line-height:.85;letter-spacing:-.07em}.tree-year span{font-size:12px;font-weight:900;margin-top:8px}.growing-tree{position:absolute;left:50%;bottom:-36px;transform-origin:50% 100%;width:min(65vw,620px);height:auto;transition:opacity .15s linear;color:#2c431f}.tree-scroll{position:absolute;right:28px;bottom:24px;font-size:12px;font-weight:900;text-transform:uppercase;letter-spacing:.1em}.tree-scroll b{font-size:18px;margin-left:6px}
.tree-events{position:relative;z-index:10;width:min(520px,calc(100% - 36px));margin-left:auto;padding:1px clamp(18px,6vw,80px) 36vh 0}.tree-events>section{background:#fffdf8;border:3px solid #111;border-radius:16px;box-shadow:0 5px 0 #111;padding:18px}.tree-events span{font-size:12px;font-weight:900}.tree-events h2{font-size:clamp(28px,3.5vw,42px);line-height:.98;letter-spacing:-.04em;margin:6px 0 10px}.tree-events p{margin:0;color:#4e4e4e}.tree-finale{margin-top:50vh!important;background:#111!important;color:#fff!important}.tree-finale p{color:#d3d3d3!important}.rings-final{margin-top:20px;color:#fff}
.mind-lab,.music-lab,.life-weeks,.conversation-wrap{max-width:1120px;margin:auto;padding:84px 22px 110px}.lab-progress{display:grid;grid-template-columns:auto 1fr auto;gap:12px;align-items:center;margin-bottom:18px;font-size:11px;font-weight:900;text-transform:uppercase;letter-spacing:.08em}.lab-progress>div{height:6px;border:2px solid #111;border-radius:999px;overflow:hidden}.lab-progress i{height:100%;display:block;background:#111}
.lab-panel{min-height:650px;background:var(--violet);border:3px solid #111;border-radius:18px;box-shadow:0 6px 0 #111;padding:clamp(22px,5vw,60px);display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center}.step-label{font-size:11px;font-weight:900;text-transform:uppercase;letter-spacing:.1em}.lab-panel h2,.mixer h2,.wave-lab h2{font-size:clamp(42px,6vw,74px);line-height:.92;letter-spacing:-.06em;margin:8px 0 15px}.instruction{max-width:700px;font-size:18px}.stroop-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px 28px;margin:34px 0;font-size:clamp(36px,6vw,68px);font-weight:900}.ink-0{color:#2f6e42}.ink-1{color:#3768b2}.ink-2{color:#854a9f}
.feedback-box{max-width:720px;background:#fff;border:2px solid #111;border-radius:14px;box-shadow:0 4px 0 #111;padding:14px 16px;text-align:left;margin-top:18px}.feedback-box strong{font-size:18px}.feedback-box p{color:#505050}.change-scene{width:min(650px,100%);height:270px;background:#fff;border:3px solid #111;border-radius:16px;display:flex;justify-content:space-evenly;align-items:center;position:relative;font-size:50px;margin:22px 0}.little-leaf{position:absolute;left:7%;top:15%;transition:left .15s}.change-scene.changed .little-leaf{left:85%}.answer-row,.memory-options{display:flex;gap:8px;flex-wrap:wrap;justify-content:center;margin:14px 0}.answer-row button,.memory-options button,.quick-years button{background:#fff;border:2px solid #111;border-radius:999px;padding:8px 12px;font-weight:800;cursor:pointer}.number-cloud{display:grid;grid-template-columns:repeat(8,58px);gap:8px;margin:26px 0}.number-cloud span{display:grid;place-items:center;aspect-ratio:1;background:#fff;border:2px solid #111;border-radius:12px;font-size:24px;font-weight:900}.memory-options button{font-size:24px;min-width:62px}.lab-explanation{max-width:760px;margin-top:34px;border-top:2px solid #111;padding-top:24px}.source-note{border-left:3px solid #111;padding-left:12px;color:#555}
.music-lab{max-width:1120px}.sound-console{min-height:390px;background:#111;color:#fff;border:3px solid #111;border-radius:18px;box-shadow:0 6px 0 #444;padding:20px;display:grid;grid-template-columns:1fr auto;align-items:start}.now-playing{display:flex;gap:10px;align-items:center}.now-playing div{display:flex;flex-direction:column}.now-playing small{color:#aaa}.pulse-dot{width:12px;height:12px;border-radius:50%;background:#555}.pulse-dot.active{background:#ffd45b;box-shadow:0 0 0 8px rgba(255,212,91,.15)}.play-button{border:0;border-radius:999px;padding:10px 14px;background:#fff;color:#111;font-weight:900;cursor:pointer}.equalizer{grid-column:1/-1;align-self:end;height:210px;display:flex;align-items:end;gap:6px}.equalizer i{flex:1;background:#ffd45b;border-radius:4px 4px 0 0;transition:height .3s}.mixer,.wave-lab{background:var(--sun);border:3px solid #111;border-radius:18px;box-shadow:0 6px 0 #111;padding:clamp(22px,5vw,52px);margin-top:20px}.track{width:100%;display:grid;grid-template-columns:100px 1fr auto;gap:10px;align-items:center;text-align:left;background:#fff;border:2px solid #111;border-radius:12px;padding:12px;margin-top:8px;cursor:pointer;opacity:.5}.track.on{opacity:1}.track>span{font-size:11px;font-weight:900;text-transform:uppercase}.track small{color:#555}.wave-lab{display:grid;grid-template-columns:1.2fr .8fr;gap:30px}.wave-controls{display:flex;flex-direction:column;gap:10px;justify-content:center}.wave-controls label{font-size:11px;font-weight:900;text-transform:uppercase}.wave-controls select{background:#fff;border:2px solid #111;border-radius:10px;padding:11px}
.conversation-wrap{max-width:1180px}.conversation-dive{min-height:760px;border:3px solid #111;border-radius:18px;box-shadow:0 6px 0 #111;background:linear-gradient(#b9e7ef,#74aebb 70%,#2f5b66);display:grid;grid-template-columns:55px 1fr 280px;gap:24px;padding:clamp(20px,4vw,44px)}.depth-meter{height:580px;border-left:3px solid rgba(17,17,17,.25);position:relative}.depth-meter>span{position:absolute;left:-3px;top:0;width:3px;background:#111}.depth-meter b{position:absolute;top:calc(100% + 7px);left:-4px;font-family:var(--serif)}.conversation-stage{align-self:center}.conversation-stage h2{font-size:clamp(44px,6vw,76px);line-height:.9;letter-spacing:-.06em;margin:8px 0 22px}.question-pair{display:grid;gap:10px}.question-pair button{background:#fff;border:2px solid #111;border-radius:14px;box-shadow:0 3px 0 #111;padding:14px;text-align:left;font-family:var(--serif);font-size:20px;display:flex;justify-content:space-between;gap:12px;cursor:pointer}.question-pair button span{font-family:var(--sans);font-size:10px;font-weight:900;text-transform:uppercase;align-self:center}.concept-card{border-left:3px solid #111;padding-left:12px}.conversation-log{align-self:center;background:rgba(255,255,255,.55);border:2px solid #111;border-radius:14px;padding:14px;font-size:13px}.conversation-log>span{font-size:10px;font-weight:900;text-transform:uppercase}.conversation-log p{display:grid;grid-template-columns:25px 1fr;gap:4px;border-top:1px solid rgba(17,17,17,.25);padding-top:8px}.conversation-ending strong{font-size:28px}
.life-weeks{max-width:1180px}.year-control{background:var(--clay);border:3px solid #111;border-radius:18px;box-shadow:0 6px 0 #111;padding:clamp(26px,5vw,56px);text-align:center}.year-control h2{font-size:clamp(48px,7vw,90px);line-height:.9;letter-spacing:-.07em;margin:8px 0}.year-control h2 span{display:block;font-family:var(--serif);font-weight:400;font-style:italic;font-size:.42em;letter-spacing:-.03em}.year-control>p:not(.step-label){max-width:680px;margin:0 auto 22px}.year-control input{width:min(700px,92%);accent-color:#111}.range-labels{display:flex;justify-content:space-between;width:min(700px,92%);margin:4px auto;font-size:11px;font-weight:800}.quick-years{display:flex;justify-content:center;gap:8px;margin-top:16px}.quick-years button.active{background:#111;color:#fff}.weeks-readout{display:flex;align-items:baseline;gap:9px;margin-top:35px}.weeks-readout strong{font-size:52px;letter-spacing:-.05em}.weeks-readout span{font-size:11px;text-transform:uppercase;font-weight:900}.weeks-grid{display:grid;grid-template-columns:repeat(52,1fr);gap:4px;margin-top:10px}.weeks-grid i{aspect-ratio:1;border:2px solid #111;border-radius:50%}.weeks-grid i.filled{background:#111}.time-prompts{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:42px}.time-prompts article{border-top:3px solid #111}.time-prompts article>span{font-family:var(--serif);font-size:46px}.time-prompts h3{font-size:24px;line-height:1;margin:5px 0}.time-prompts p{color:#555}.life-quote{font-family:var(--serif);font-size:clamp(38px,5.5vw,70px);line-height:1;text-align:center;margin:90px auto 0;max-width:950px}
.info-page{max-width:1080px;margin:auto;padding:0 22px 90px}.info-nav{height:88px;border-bottom:2px solid #111;display:flex;align-items:center;justify-content:space-between}.info-page article{padding-top:78px}.info-kicker{font-size:12px;font-weight:900;text-transform:uppercase;letter-spacing:.1em}.info-page h1{font-size:clamp(52px,8vw,100px);line-height:.9;letter-spacing:-.07em;margin:10px 0 28px}.info-page h1 em{font-family:var(--serif);font-weight:400}.info-lead{font-family:var(--serif);font-size:clamp(21px,3vw,30px);max-width:820px;color:#444}.principles{display:grid;grid-template-columns:repeat(2,1fr);gap:16px;margin-top:65px}.principles section{border:3px solid #111;border-radius:16px;padding:18px}.principles section>span{font-size:11px;font-weight:900}.principles h2{font-size:32px;letter-spacing:-.04em;margin:15px 0 7px}.principles p{color:#555}.info-end,.credits-box{margin-top:50px;background:#111;color:#fff;border-radius:16px;padding:22px}.info-end strong{font-size:42px}.info-end p,.credits-box p{color:#ccc}.sources-list{margin-top:60px;border-top:3px solid #111}.sources-list section{display:grid;grid-template-columns:55px 1fr;gap:16px;border-bottom:2px solid #111;padding:22px 0}.sources-list section>span{font-size:11px;font-weight:900}.sources-list h2{font-size:30px;margin:0 0 7px}.sources-list p{color:#555}.sources-list a{font-weight:800;border-bottom:2px solid #111}
.not-found{min-height:100vh;display:grid;place-items:center;align-content:center;text-align:center;padding:22px}.not-found h1{font-size:clamp(54px,9vw,110px);line-height:.9;letter-spacing:-.07em;margin:10px}.not-found p{color:#555;max-width:520px}
@media(max-width:900px){
 .play-grid{grid-template-columns:1fr}.play-tile{min-height:460px}.experience-cover{grid-template-columns:1fr;min-height:auto;padding-top:110px}.cover-art{order:-1}.cover-art .tile-art{width:min(85%,420px)}.next-tile{grid-template-columns:auto 110px 1fr}.next-tile strong{display:none}
 .wave-lab{grid-template-columns:1fr}.conversation-dive{grid-template-columns:38px 1fr}.conversation-log{grid-column:2}.time-prompts{grid-template-columns:1fr}.weeks-grid{grid-template-columns:repeat(26,1fr)}.principles{grid-template-columns:1fr}
}
@media(max-width:600px){
 .home-page{padding-inline:14px}.home-header{height:72px}.home-brand small{display:none}.home-header nav{font-size:13px}.home-intro{padding:58px 0 42px}.home-intro h1{font-size:55px}.play-grid{gap:14px}.play-tile{min-height:410px;padding:12px;border-width:2px;box-shadow:0 4px 0 #111}.tile-visual{min-height:200px;padding:8px}.tile-copy h2{font-size:36px}.tile-bar span{border-width:1.5px}.home-footer{display:block}.home-footer span{display:block;margin-top:5px}
 .experience-nav{left:10px;right:10px;top:10px}.experience-cover{padding:92px 16px 48px}.experience-cover h1{font-size:54px}.cover-art .tile-art{width:100%}.cover-actions{align-items:flex-start;flex-direction:column}.next-card{padding-inline:14px}.next-tile{grid-template-columns:auto 80px 1fr;padding:12px}.next-tile h2{font-size:20px}
 .mind-lab,.music-lab,.life-weeks,.conversation-wrap{padding:60px 14px 85px}.lab-panel{min-height:580px;padding:18px}.lab-panel h2,.mixer h2,.wave-lab h2{font-size:42px}.stroop-grid{grid-template-columns:repeat(2,1fr);font-size:33px}.number-cloud{grid-template-columns:repeat(4,52px)}.change-scene{height:230px}.instruction-banner{display:block}.instruction-banner>span{display:block;margin-bottom:5px}
 .sound-console{grid-template-columns:1fr;gap:14px}.equalizer{height:150px}.track{grid-template-columns:76px 1fr}.track small{grid-column:2}.conversation-dive{padding:14px;grid-template-columns:25px 1fr;gap:12px}.question-pair button{display:block}.question-pair button span{display:block;margin-top:8px}.weeks-grid{grid-template-columns:repeat(13,1fr);gap:5px}.tree-events{padding-right:18px}.tree-year{top:75px}.growing-tree{width:95vw}.tree-scroll{right:14px}
 .info-page{padding-inline:14px}.info-nav{height:72px}.info-page article{padding-top:52px}.info-page h1{font-size:52px}.sources-list section{grid-template-columns:40px 1fr}
}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*::before,*::after{transition:none!important;animation:none!important}}


/* app/experiences.css */
/* Experiências refeitas: árvore, percepção e conversa */

.tree-trip{min-height:5200px;background:#c7dda9;position:relative;color:#111}
.tree-trip-sticky{position:sticky;top:0;height:100vh;overflow:hidden;background:linear-gradient(180deg,#dff0c7 0%,#b9d599 100%)}
.tree-ghost-word{position:absolute;inset:50% auto auto 50%;transform:translate(-50%,-58%);font-size:clamp(100px,22vw,330px);font-weight:900;letter-spacing:-.09em;color:rgba(255,255,255,.34);white-space:nowrap;pointer-events:none}
.tree-time{position:absolute;left:clamp(18px,5vw,70px);top:76px;z-index:5;display:flex;flex-direction:column}
.tree-time small{font-size:11px;font-weight:900;letter-spacing:.12em;text-transform:uppercase}.tree-time strong{font-size:clamp(68px,10vw,132px);line-height:.85;letter-spacing:-.07em}
.tree-main{position:absolute;left:50%;bottom:-120px;width:min(58vw,650px);transform-origin:50% 100%;color:#244316;transition:transform .12s linear}
.tree-moment{position:absolute;z-index:6;right:clamp(18px,6vw,86px);top:50%;transform:translateY(-50%);width:min(390px,42vw);animation:moment-in .25s ease}
.tree-moment span{display:inline-block;background:#fff;border:2px solid #111;border-radius:999px;padding:5px 9px;font-size:11px;font-weight:900}
.tree-moment h2{font-size:clamp(36px,5vw,68px);line-height:.9;letter-spacing:-.06em;margin:12px 0}.tree-moment p{font-size:17px;max-width:360px}
.tree-ruler{position:absolute;left:50%;bottom:26px;transform:translateX(-50%);display:flex;width:min(720px,72vw);justify-content:space-between;z-index:7}
.tree-ruler:before{content:"";position:absolute;left:0;right:0;top:5px;height:2px;background:rgba(17,17,17,.25)}
