.chalk-card.compact{width:min(100%,300px)}
.tile-visual{display:grid;place-items:center;padding:10px!important}
.tile-visual:before,.cover-art:before{display:none!important}
.cover-art{display:grid;place-items:center}
.cover-art .chalk-card{width:min(100%,520px)}
